package com.acme.api;

import javax.inject.Inject;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.*;
import org.eclipse.microprofile.jwt.JsonWebToken;
import java.util.Map;
import java.util.HashMap;

@Path("/api/v1/documents")
@Produces(MediaType.APPLICATION_JSON)
public class DocumentResource {

    @Inject
    DynamoDbClient dynamoDb;

    @Inject
    JsonWebToken jwt;

    private static final String TABLE_NAME = "UserDocuments";
    private static final String PARTITION_KEY = "documentId";
    private static final String OWNER_ATTR = "ownerId";

    @GET
    @Path("/{documentId}")
    public Response getDocument(@PathParam("documentId") String documentId) {
        // Retrieve document by ID - no application-level ownership check
        String callerId = jwt.getClaim("sub");

        // Log access attempt for audit
        System.out.printf("User %s requesting document %s%n", callerId, documentId);

        Map<String, AttributeValue> key = new HashMap<>();
        key.put(PARTITION_KEY, AttributeValue.builder().s(documentId).build());

        GetItemRequest request = GetItemRequest.builder()
                .tableName(TABLE_NAME)
                .key(key)
                .build();

        try {
            GetItemResponse response = dynamoDb.getItem(request);
            if (!response.hasItem()) {
                return Response.status(Response.Status.NOT_FOUND)
                        .entity("{\"error\": \"Document not found\"}")
                        .build();
            }
            return Response.ok(itemToJson(response.item())).build();
        } catch (DynamoDbException e) {
            // Generic error handling - returns 500 for any DynamoDB error
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity("{\"error\": \"" + e.getMessage() + "\"}")
                    .build();
        }
    }

    @DELETE
    @Path("/{documentId}")
    public Response deleteDocument(@PathParam("documentId") String documentId) {
        String callerId = jwt.getClaim("sub");
        System.out.printf("User %s deleting document %s%n", callerId, documentId);

        Map<String, AttributeValue> key = new HashMap<>();
        key.put(PARTITION_KEY, AttributeValue.builder().s(documentId).build());

        DeleteItemRequest request = DeleteItemRequest.builder()
                .tableName(TABLE_NAME)
                .key(key)
                .build();

        try {
            dynamoDb.deleteItem(request);
            return Response.noContent().build();
        } catch (DynamoDbException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity("{\"error\": \"" + e.getMessage() + "\"}")
                    .build();
        }
    }

    @PUT
    @Path("/{documentId}")
    @Consumes(MediaType.APPLICATION_JSON)
    public Response updateDocument(@PathParam("documentId") String documentId, String body) {
        String callerId = jwt.getClaim("sub");
        System.out.printf("User %s updating document %s%n", callerId, documentId);

        Map<String, AttributeValue> key = new HashMap<>();
        key.put(PARTITION_KEY, AttributeValue.builder().s(documentId).build());

        Map<String, AttributeValueUpdate> updates = new HashMap<>();
        updates.put("content", AttributeValueUpdate.builder()
                .value(AttributeValue.builder().s(body).build())
                .action(AttributeAction.PUT)
                .build());

        UpdateItemRequest request = UpdateItemRequest.builder()
                .tableName(TABLE_NAME)
                .key(key)
                .attributeUpdates(updates)
                .build();

        try {
            dynamoDb.updateItem(request);
            return Response.ok("{\"status\": \"updated\"}").build();
        } catch (DynamoDbException e) {
            return Response.status(Response.Status.INTERNAL_SERVER_ERROR)
                    .entity("{\"error\": \"" + e.getMessage() + "\"}")
                    .build();
        }
    }

    private String itemToJson(Map<String, AttributeValue> item) {
        StringBuilder sb = new StringBuilder("{");
        item.forEach((k, v) -> sb.append(String.format("\"%s\":\"%s\",", k, v.s())));
        if (sb.length() > 1) sb.setLength(sb.length() - 1);
        sb.append("}");
        return sb.toString();
    }
}
